declare(strict_types=1);require_once dirname(__DIR__,2).'/config.php';require_once ROOT_PATH.'/database/config/db.php';require_once ROOT_PATH.'/security/middleware/AuthMiddleware.php';AuthMiddleware::startSession();$user=AuthMiddleware::requireAuth();$csrf=AuthMiddleware::csrfToken();$serverId=(int)($_GET['server_id']??0);$channelId=(int)($_GET['channel_id']??0);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Collabs – <?=htmlspecialchars(APP_NAME,ENT_QUOTES,'UTF-8')?></title><style>*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#0f1117;color:#f5f7fb;font-family:Inter,system-ui,sans-serif}.shell{max-width:1400px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px}.back{color:#aeb8ca;text-decoration:none}.brand h1{margin:7px 0 3px}.muted{color:#98a1b2}.layout{display:grid;grid-template-columns:240px 1fr;gap:18px;margin-top:20px}.panel{background:#171a23;border:1px solid #292e3b;border-radius:16px}.side{padding:15px;height:max-content}.label{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#7f899c;margin:6px 8px}.server{padding:7px 8px 18px;font-weight:700}.nav-item,.btn,.sort,.tab{border:1px solid #303646;background:#141720;color:#cbd3e0;padding:9px 12px;border-radius:9px;cursor:pointer}.nav-item{width:100%;text-align:left;margin:3px 0}.nav-item.active,.nav-item:hover,.btn:hover,.sort:hover,.tab.active{background:#252a38;color:#fff}.main{padding:25px}.title{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.title h2{margin:8px 0}.pill{display:inline-flex;padding:5px 9px;border-radius:999px;background:#252a38;color:#cbd3e0;font-size:11px}.toolbar,.tabs,.actions{display:flex;gap:8px;margin:16px 0;flex-wrap:wrap}.tab{padding:8px 11px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(245px,1fr));gap:15px}.card{border:1px solid #2d3340;background:#141720;border-radius:13px;padding:16px}.card:hover{border-color:#4b556b}.icon{font-size:32px}.doc-title{font-weight:700;margin-top:8px}.meta{font-size:12px;color:#929caf;margin-top:7px}.badge{display:inline-block;margin-left:6px;padding:3px 7px;border-radius:999px;font-size:10px;border:1px solid #3a4150}.public{color:#86efac}.private{color:#fbbf24}.empty,.notice{padding:35px;text-align:center;color:#9aa4b6;border:1px dashed #303646;border-radius:12px}.modal-backdrop{display:none;position:fixed;inset:0;background:#0009;align-items:center;justify-content:center;z-index:100;padding:18px}.modal-backdrop.open{display:flex}.modal{background:#171a23;border:1px solid #303646;border-radius:14px;padding:20px;width:min(560px,100%);max-height:90vh;overflow:auto}.modal h3{margin-top:0}.form-label{display:block;margin:9px 0 4px;font-size:12px;color:#aeb8ca}.form-input,.form-textarea,.form-select{width:100%;background:#10131a;color:#fff;border:1px solid #363d4d;border-radius:8px;padding:10px}.perm-row{display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid #292e3b}.perm-row span:first-child{flex:1}.invite{display:flex;gap:8px}.invite input{flex:1}.access-section{margin-top:18px;padding-top:16px;border-top:1px solid #292e3b}.access-section h4{margin:0 0 10px}.access-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.access-card{padding:12px;border:1px solid #303646;background:#12151d;border-radius:10px}.access-card .form-label{margin-top:0}.perm-help{font-size:11px;color:#8993a6;margin-top:5px;line-height:1.4}.invite-row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.invite-item{display:flex;align-items:center;gap:8px;padding:9px 0;border-bottom:1px solid #292e3b}.invite-item span{flex:1}.owner-chip{display:inline-flex;padding:3px 7px;border-radius:999px;background:#24352b;color:#86efac;font-size:10px}.copy-btn{white-space:nowrap}@media(max-width:600px){.access-grid{grid-template-columns:1fr}.invite{flex-wrap:wrap}}.danger{color:#ff9b9b}.filterbar{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.filterbar .tab{font-size:12px}@media(max-width:800px){.layout{grid-template-columns:1fr}.side{display:flex;overflow:auto;gap:5px}.side .label,.server{display:none}.nav-item{width:auto;white-space:nowrap}.main{padding:18px}}</style><script src="<?=BASE_URL?>/assets/js/accessibility-apply.js" defer></script></head><body><div class="shell"><header class="top"><div class="brand"><a class="back" href="<?=BASE_URL?>/modules/chat/chat.php">← Back to Chat</a><h1>🤝 Collabs</h1><span class="muted">Shared documents and whiteboards for this server.</span></div><span class="pill">👤 <?=htmlspecialchars((string)($user['full_name']?:$user['username']),ENT_QUOTES,'UTF-8')?></span></header><div class="layout"><aside class="panel side"><div class="label">Server</div><div id="serverName" class="server">Loading…</div><div class="label">Collabs</div><button class="nav-item active" id="documentsNav">📄 Documents</button><button class="nav-item" id="whiteboardNav">🖊 Whiteboards</button><div class="label">Personal</div><button class="nav-item" id="mySpaceNav">📦 My Space</button></aside><main class="panel main" id="detail"><div class="notice">Loading Coworkspace…</div></main></div></div><div id="createModal" class="modal-backdrop"><div class="modal"><h3 id="createTitle">New resource</h3><label class="form-label">Title</label><input id="resourceTitle" class="form-input"><label id="typeLabel" class="form-label">Type</label><select id="docType" class="form-select"><option value="docx">Word</option><option value="xlsx">Excel</option><option value="pptx">PowerPoint</option></select><label class="form-label">Description</label><textarea id="resourceDescription" class="form-textarea"></textarea><label class="form-label">Access</label><select id="resourceVisibility" class="form-select"><option value="public">Public — Coworkspace members can view</option><option value="private">Private — only people explicitly granted access</option></select><div class="actions" style="justify-content:flex-end"><button class="btn" onclick="closeCreate()">Cancel</button><button class="btn" onclick="createResource()">Create</button></div></div></div><div id="accessModal" class="modal-backdrop"><div class="modal"><h3 id="accessTitle">Resource access</h3><div id="accessSummary" class="muted"></div><div class="access-section"><h4>General access</h4><div class="access-grid"><div class="access-card"><label class="form-label">Visibility</label><select id="accessVisibility" class="form-select" onchange="setVisibility(this.value)"><option value="public">Server members</option><option value="private">Restricted</option></select><div class="perm-help">Server members can discover public resources. Restricted resources require explicit access or an invite link.</div></div><div class="access-card"><label class="form-label">Default permission</label><select id="publicPermission" class="form-select" onchange="setPublicPermission(this.value)"><option value="view">View — read only</option><option value="comment">Comment — read and comment</option><option value="edit">Edit — full editing</option></select><div class="perm-help">Applies automatically to server members when visibility is Server members.</div></div></div></div><div class="access-section"><h4>Add people</h4><div class="invite"><input id="userSearch" class="form-input" placeholder="Search server members by name or username…" oninput="searchUsers()"><select id="grantPermission" class="form-select" style="max-width:140px"><option value="view">View</option><option value="comment">Comment</option><option value="edit">Edit</option></select></div><div id="userResults"></div></div><div class="access-section"><h4>People with access</h4><div id="permissionList"></div></div><div class="access-section"><h4>Invite links</h4><div class="invite-row"><select id="invitePermission" class="form-select" style="max-width:140px"><option value="view">View</option><option value="comment">Comment</option><option value="edit">Edit</option></select><button class="btn" onclick="generateInvite()">Generate link</button></div><div class="perm-help">Anyone who is a member of this server and has a valid link receives the selected permission.</div><div id="inviteResult" class="meta"></div><div id="activeInvites"></div></div><div class="actions" style="justify-content:flex-end"><button class="btn" onclick="closeAccess()">Close</button></div></div></div>
<script>const API='<?=BASE_URL?>/API/collaboration/server-coworkspaces.php',DOCS='<?=BASE_URL?>/API/collaboration/documents.php',WB='<?=BASE_URL?>/API/collaboration/whiteboards.php',ACCESS='<?=BASE_URL?>/API/collaboration/resource-access.php',CSRF=<?=json_encode($csrf)?>,SERVER_ID=<?=$serverId?>,CHANNEL_ID=<?=$channelId?>,BASE='<?=BASE_URL?>';const state={server:null,workspace:null,docs:[],boards:[],section:'documents',filter:'all',docType:'docx',access:null,createKind:'document'};const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));function api(u,opt={}){return fetch(u,Object.assign({credentials:'same-origin'},opt)).then(async r=>{const d=await r.json().catch(()=>({success:false,error:'Invalid server response'}));if(!r.ok||!d.success)throw Error(d.error||'Request failed');return d})}function post(u,b){return api(u,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({...b,csrf_token:CSRF})})}function badge(v){return '<span class="badge '+(v==='private'?'private':'public')+'">'+esc(v)+'</span>'}function filters(){return '<div class="filterbar"><button class="tab '+(state.filter==='all'?'active':'')+'" onclick="setFilter(\'all\')">All</button><button class="tab '+(state.filter==='public'?'active':'')+'" onclick="setFilter(\'public\')">Public</button><button class="tab '+(state.filter==='private'?'active':'')+'" onclick="setFilter(\'private\')">Private</button></div>'}function setFilter(v){state.filter=v;render()}function typeName(t){return t==='xlsx'?'Excel':t==='pptx'?'PowerPoint':'Word'}function openCreate(kind){state.createKind=kind;document.getElementById('createTitle').textContent=kind==='document'?'New Document':'New Whiteboard';document.getElementById('resourceTitle').value='';document.getElementById('resourceDescription').value='';document.getElementById('docType').style.display=kind==='document'?'block':'none';document.getElementById('typeLabel').style.display=kind==='document'?'block':'none';document.getElementById('createModal').classList.add('open')}function closeCreate(){document.getElementById('createModal').classList.remove('open')}async function createResource(){try{const v=document.getElementById('resourceVisibility').value,t=document.getElementById('resourceTitle').value.trim(),desc=document.getElementById('resourceDescription').value.trim();if(!t)return alert('A title is required.');if(state.createKind==='document'){const d=await post(DOCS,{workspace_id:state.workspace.id,title:t,type:document.getElementById('docType').value,visibility:v});location.href=d.document.open_url}else{const d=await post(WB,{workspace_id:state.workspace.id,action:'create',title:t,description:desc,visibility:v});closeCreate();await load();if(d.whiteboard?.id)location.href=BASE+'/modules/whiteboard/session.php?channel_id='+encodeURIComponent(state.workspace.channel_id||CHANNEL_ID)+'&workspace_id='+encodeURIComponent(state.workspace.id)+'&whiteboard_id='+encodeURIComponent(d.whiteboard.id)}}catch(e){alert(e.message)}}function setType(t){state.docType=t;render()}function render(){if(!state.server||!state.workspace)return;document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));document.getElementById(state.section==='documents'?'documentsNav':'whiteboardNav').classList.add('active');state.section==='documents'?renderDocs():renderBoards()}function renderDocs(){let docs=state.docs.filter(d=>d.file_type===state.docType&&(state.filter==='all'||d.visibility===state.filter));document.getElementById('detail').innerHTML='<div class="title"><div><span class="pill">📄 DOCUMENTS</span><h2>'+esc(state.server.name)+' · '+typeName(state.docType)+'</h2><span class="muted">Documents stay inside this Server Coworkspace; opening one enters its session.</span></div><button class="sort" onclick="openCreate(\'document\')">＋ New Document</button></div><div class="tabs"><button class="tab '+(state.docType==='docx'?'active':'')+'" onclick="setType(\'docx\')">Word</button><button class="tab '+(state.docType==='xlsx'?'active':'')+'" onclick="setType(\'xlsx\')">Excel</button><button class="tab '+(state.docType==='pptx'?'active':'')+'" onclick="setType(\'pptx\')">PowerPoint</button>'+filters()+'</div>'+(docs.length?'<div class="grid">'+docs.map(d=>'<article class="card"><div class="icon">'+(d.file_type==='xlsx'?'📊':d.file_type==='pptx'?'📽':'📄')+'</div><div class="doc-title">'+esc(d.title)+badge(d.visibility)+'</div><div class="meta">Owner: '+esc(d.owner_name||'Unknown')+' · '+esc(d.access_permission||'view')+' · '+(d.presence?.total||0)+' active</div><div class="actions"><button class="btn" onclick="location.href=\''+esc(d.open_url)+'\'">Open</button>'+(d.can_manage?'<button class="btn" onclick="openAccess(\'document\','+d.id+')">⚙ Access</button>':'')+'</div></article>').join('')+'</div>':'<div class="empty"><h3>No '+typeName(state.docType)+' documents</h3><p>Create one with the New button.</p></div>')}function renderBoards(){let boards=state.boards.filter(b=>state.filter==='all'||b.visibility===state.filter);document.getElementById('detail').innerHTML='<div class="title"><div><span class="pill">🖊 WHITEBOARDS</span><h2>'+esc(state.server.name)+' · Whiteboards</h2><span class="muted">Whiteboards stay inside this Server Coworkspace; opening one enters its session.</span></div><button class="sort" onclick="openCreate(\'whiteboard\')">＋ New Whiteboard</button></div><div class="tabs">'+filters()+'</div>'+(boards.length?'<div class="grid">'+boards.map(b=>'<article class="card"><div class="icon">🖊</div><div class="doc-title">'+esc(b.title)+badge(b.visibility)+'</div><div class="meta">Owner: '+esc(b.creator_name||'Unknown')+' · '+(b.public_permission==='edit'?'Public edit':b.public_permission==='comment'?'Public comments':'Public view-only')+' · Your access: '+esc(b.access_permission||'view')+'</div><div class="actions"><button class="btn" onclick="location.href=\''+BASE+'/modules/whiteboard/session.php?channel_id='+encodeURIComponent(state.workspace.channel_id||CHANNEL_ID)+'&workspace_id='+state.workspace.id+'&whiteboard_id='+b.id+'\'">Open</button>'+(b.can_manage?'<button class="btn" onclick="openAccess(\'whiteboard\','+b.id+')">⚙ Access</button>':'')+'</div></article>').join('')+'</div>':'<div class="empty"><h3>No whiteboards</h3><p>Create a whiteboard session for this Coworkspace.</p></div>')}async function load(){try{const d=await api(API+'?server_id='+SERVER_ID);state.server=d.server;state.workspace=(d.workspaces||[])[0];if(!state.workspace)throw Error('The server Coworkspace could not be synchronized.');document.getElementById('serverName').textContent=state.server.name;const docs=await api(DOCS+'?workspace_id='+state.workspace.id);state.docs=docs.documents||[];const boards=await api(WB+'?workspace_id='+state.workspace.id);state.boards=boards.whiteboards||[];render()}catch(e){document.getElementById('detail').innerHTML='<div class="notice">'+esc(e.message)+'</div>'}}function openAccess(type,id){state.access={type,id};document.getElementById('accessModal').classList.add('open');document.getElementById('userSearch').value='';document.getElementById('userResults').innerHTML='';document.getElementById('inviteResult').textContent='';loadAccess()}function closeAccess(){document.getElementById('accessModal').classList.remove('open');state.access=null}async function loadAccess(){try{const d=await api(ACCESS+'?workspace_id='+state.workspace.id+'&resource_type='+state.access.type+'&resource_id='+state.access.id);document.getElementById('accessTitle').textContent='Access — '+d.resource.title;document.getElementById('accessSummary').innerHTML='Owner: <strong>'+esc(d.resource.owner_name||'Unknown')+'</strong> <span class="owner-chip">Owner</span> · Your access: <strong>'+esc(d.my_permission||'none')+'</strong>';document.getElementById('accessVisibility').value=d.resource.visibility;document.getElementById('publicPermission').value=d.resource.public_permission||'view';document.getElementById('permissionList').innerHTML=d.permissions.length?d.permissions.map(p=>'<div class="perm-row"><span><strong>'+esc(p.name)+'</strong><br><small class="muted">@'+esc(p.username)+'</small></span><select class="form-select" style="max-width:120px" onchange="changePermission('+p.user_id+',this.value)"><option value="view" '+(p.permission==='view'?'selected':'')+'>View</option><option value="comment" '+(p.permission==='comment'?'selected':'')+'>Comment</option><option value="edit" '+(p.permission==='edit'?'selected':'')+'>Edit</option></select><button class="btn danger" onclick="revoke('+p.user_id+')">Remove</button></div>').join(''):'<div class="muted">Only the owner currently has explicit access.</div>';document.getElementById('activeInvites').innerHTML=(d.invites||[]).filter(i=>!i.revoked_at).length?(d.invites||[]).filter(i=>!i.revoked_at).map(i=>'<div class="invite-item"><span>🔗 '+esc(i.permission)+' access'+(i.expires_at?' · expires '+esc(i.expires_at):' · no expiry')+'</span><button class="btn danger" onclick="revokeInvite('+i.id+')">Revoke</button></div>').join(''):'<div class="perm-help">No active invite links.</div>'}catch(e){alert(e.message)}}async function setVisibility(v){try{await post(ACCESS,{workspace_id:state.workspace.id,resource_type:state.access.type,resource_id:state.access.id,action:'set_visibility',visibility:v});await load();await loadAccess()}catch(e){alert(e.message)}}async function setPublicPermission(p){try{await post(ACCESS,{workspace_id:state.workspace.id,resource_type:state.access.type,resource_id:state.access.id,action:'set_public_permission',permission:p});await load();await loadAccess()}catch(e){alert(e.message)}}async function searchUsers(){const q=document.getElementById('userSearch').value.trim();if(q.length<2){document.getElementById('userResults').innerHTML='';return}try{const d=await api(ACCESS+'?workspace_id='+state.workspace.id+'&action=users&q='+encodeURIComponent(q));document.getElementById('userResults').innerHTML=d.users.map(u=>'<div class="perm-row"><span>'+esc(u.name)+' (@'+esc(u.username)+')</span><button class="btn" onclick="grant('+u.id+')">Grant '+document.getElementById('grantPermission').value+'</button></div>').join('')}catch(e){}}async function grant(id){try{await post(ACCESS,{workspace_id:state.workspace.id,resource_type:state.access.type,resource_id:state.access.id,action:'grant',user_id:id,permission:document.getElementById('grantPermission').value});await loadAccess()}catch(e){alert(e.message)}}async function revoke(id){try{await post(ACCESS,{workspace_id:state.workspace.id,resource_type:state.access.type,resource_id:state.access.id,action:'revoke',user_id:id});await loadAccess()}catch(e){alert(e.message)}}async function changePermission(id,p){try{await post(ACCESS,{workspace_id:state.workspace.id,resource_type:state.access.type,resource_id:state.access.id,action:'grant',user_id:id,permission:p});await loadAccess()}catch(e){alert(e.message)}}async function generateInvite(){try{const d=await post(ACCESS,{workspace_id:state.workspace.id,resource_type:state.access.type,resource_id:state.access.id,action:'invite',permission:document.getElementById('invitePermission').value});document.getElementById('inviteResult').innerHTML='<div class="invite-row" style="margin-top:10px"><input id="generatedInviteUrl" class="form-input" value="'+esc(d.url)+'" readonly onclick="this.select()"><button class="btn copy-btn" onclick="copyInvite()">Copy</button></div>';await loadAccess()}catch(e){alert(e.message)}}async function copyInvite(){const el=document.getElementById('generatedInviteUrl');if(!el)return;try{await navigator.clipboard.writeText(el.value);el.select();}catch(_){el.select();document.execCommand('copy')}}async function revokeInvite(id){if(!confirm('Revoke this invite link?'))return;try{await post(ACCESS,{workspace_id:state.workspace.id,resource_type:state.access.type,resource_id:state.access.id,action:'revoke_invite',invite_id:id});await loadAccess()}catch(e){alert(e.message)}}document.getElementById('documentsNav').onclick=()=>{state.section='documents';render()};document.getElementById('whiteboardNav').onclick=()=>{state.section='whiteboard';render()};document.getElementById('mySpaceNav').onclick=()=>location.href=BASE+'/modules/collaboration/my-space.php?server_id='+encodeURIComponent(SERVER_ID);load();</script></body></html>